<section id="activity" class="settings-section"><div class="section-intro"><span class="eyebrow">Audit history</span><h2>Recent activity</h2><p>Security and administration changes are recorded with the responsible user and IP address.</p></div><div class="activity-list"><?php if(!$activity): ?><p class="muted">No activity has been recorded yet.</p><?php endif; ?><?php foreach($activity as $item): ?><div><span class="activity-icon">•</span><span><strong><?= htmlspecialchars(ucwords(str_replace(['.','_'],' ',$item['action']))) ?></strong><small><?= htmlspecialchars((string)($item['description']?:'System activity')) ?></small></span><span><strong><?= htmlspecialchars((string)($item['user_name']?:'System')) ?></strong><small><?= date('j M Y, H:i',strtotime($item['created_at'])) ?> · <?= htmlspecialchars((string)$item['ip_address']) ?></small></span></div><?php endforeach; ?></div></section>
